manifests.text:
[package]
description   = "SWC helpers for the React Compiler"
documentation = "https://rustdoc.swc.rs/swc_ecma_react_compiler/"
edition       = { workspace = true }
license       = { workspace = true }
name          = "swc_ecma_react_compiler"
repository    = { workspace = true }
version       = "26.0.1"


[package.metadata.docs.rs]
all-features = true
rustdoc-args = ["--cfg", "docsrs"]

[dependencies]
indexmap           = { workspace = true, features = ["serde"] }
react_compiler     = { version = "=0.1.0", package = "react_compiler" }
react_compiler_ast = { version = "=0.1.0", package = "react_compiler_ast" }
react_compiler_hir = { version = "=0.1.0", package = "react_compiler_hir" }
rustc-hash         = { workspace = true }
serde              = { workspace = true, features = ["derive"] }
serde_json         = { workspace = true }
swc_atoms          = { version = "10.0.0", path = "../swc_atoms" }
swc_common         = { version = "26.0.0", path = "../swc_common" }
swc_ecma_ast       = { version = "29.0.2", path = "../swc_ecma_ast" }
swc_ecma_codegen   = { version = "32.0.5", path = "../swc_ecma_codegen" }
swc_ecma_parser    = { version = "46.1.2", path = "../swc_ecma_parser", default-features = false, features = [
  "typescript",
] }
swc_ecma_utils     = { version = "35.1.0", path = "../swc_ecma_utils", features = ["stacker"] }
swc_ecma_visit     = { version = "29.0.0", path = "../swc_ecma_visit" }

[dev-dependencies]
swc_common      = { version = "26.0.0", path = "../swc_common" }
swc_ecma_parser = { version = "46.1.2", path = "../swc_ecma_parser", default-features = false, features = [
  "typescript",
] }
testing         = { version = "27.0.0", path = "../testing" }

{
  "name": "babel-plugin-react-compiler-rust",
  "version": "0.0.0-experimental",
  "description": "Babel plugin for React Compiler (Rust backend).",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "license": "MIT",
  "files": [
    "dist",
    "!*.tsbuildinfo"
  ],
  "scripts": {
    "build": "tsc",
    "watch": "tsc --watch",
    "snap": "yarn workspace snap run snap",
    "snap:build": "yarn workspace snap run build",
    "snap:ci": "yarn snap:build && yarn snap --rust",
    "test": "yarn snap:ci"
  },
  "dependencies": {
    "@babel/types": "^7.26.0"
  },
  "devDependencies": {
    "@babel/core": "^7.2.0",
    "typescript": "^5.0.0"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/react/react.git",
    "directory": "compiler/packages/babel-plugin-react-compiler-rust"
  }
}
